return ['domain'=>'wpml-import','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'sv_SE','project-id-version'=>'WPML Export and Import 5.0.0','pot-creation-date'=>'2026-09-15T17:43:02+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Export and Import'=>'WPML Export and Import','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/','A multipurpose plugin to export and import multilingual content.'=>'Ett mångsidigt tillägg för att exportera och importera flerspråkigt innehåll.','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com'=>'http://www.onthegosystems.com','The import trigger no longer accepts the key in the URL. Send it in a POST body.'=>'Importutlösaren accepterar inte längre nyckeln i URL:en. Skicka den i en POST-body.','Method Not Allowed'=>'Metoden tillåts inte','Unauthorized'=>'Obehörig','No items to process'=>'Inga objekt att bearbeta','No Content'=>'Inget innehåll','Import process completed'=>'Importprocessen slutförd','Success'=>'Lyckades','Import process failed'=>'Importprocessen misslyckades','Internal Server Error'=>'Internt serverfel','%1$s: %2$d item could not be processed and was skipped.'=>'%1$s: %2$d objekt kunde inte bearbetas och hoppades över.' . "\0" . '%1$s: %2$d objekt kunde inte bearbetas och hoppades över.','Cleaning Up Post Data'=>'Rensning av inläggsdata','Removing temporary and import-related post meta data.'=>'Tar bort tillfällig och importrelaterad metadata för inlägg.','Cleaning Up Term Data'=>'Rensning av termdata','Removing temporary and import-related term meta data.'=>'Tar bort tillfällig och importrelaterad metadata för termer.','Connecting Post Image Attachments'=>'Koppling av bilagor för inläggsbilder','Updating thumbnail and gallery attachment IDs on translated posts, products, and CPTs to point to their translated equivalents.'=>'Uppdaterar ID:n för utvalda bilder och galleribilagor på översatta inlägg, produkter och anpassade inläggstyper så att de pekar på sina översatta motsvarigheter.','Connecting Inline Term Translations'=>'Koppling av inbäddade termöversättningar','Scanning posts with a single taxonomy term in order to identify and connect the terms assigned to these posts with their translations.'=>'Skannar inlägg med en enskild taxonomiterm för att identifiera och koppla termerna som tilldelats dessa inlägg till deras översättningar.','Deleting Obsolete Original Terms'=>'Borttagning av föråldrade originaltermer','Removing original terms that are no longer needed after creating duplicates for same-named terms. Ensuring no posts are linked to these original terms.'=>'Tar bort originaltermer som inte längre behövs efter att dubbletter skapats för termer med samma namn. Säkerställer att inga inlägg är länkade till dessa originaltermer.','Duplicating Terms with Shared Names Across Languages'=>'Duplicering av termer med delade namn mellan språk','Creating duplicates in the correct language for terms that share the same name across languages, but belong to posts in different languages.'=>'Skapar dubbletter på rätt språk för termer som delar samma namn mellan språk, men som tillhör inlägg på olika språk.','Fixing Imported Post Slugs'=>'Korrigering av importerade inläggssluggar','Regenerating translated post slugs to prevent conflicts with the originals.'=>'Regenererar översatta inläggssluggar för att förhindra konflikter med originalen.','Clearing Translations Cache'=>'Rensning av översättningscache','Invalidating the persistent cache so it can be regenerated.'=>'Ogiltigförklarar den persistenta cachen så att den kan återskapas.','Marking Parent Terms for Connection'=>'Markering av överordnade termer för koppling','Collecting parent terms to connect their translations in the next step.'=>'Samlar in överordnade termer för att koppla deras översättningar i nästa steg.','Connecting Posts with Correct Term Translations'=>'Koppling av inlägg till korrekta termöversättningar','Ensuring posts are connected to terms in the correct language, especially if you have the same term names across languages.'=>'Säkerställer att inlägg är kopplade till termer på rätt språk, särskilt om du har samma termnamn på flera språk.','Sending Posts for Automatic Translation'=>'Sändning av inlägg för automatisk översättning','Creating automatic translation jobs for posts flagged for auto-translation in the exported data.'=>'Skapar automatiska översättningsjobb för inlägg som markerats för automatisk översättning i den exporterade datan.','Setting Attachments\' Language'=>'Inställning av bilagors språk','Assigning a language to imported attachments.'=>'Tilldelar ett språk till importerade bilagor.','Updating Final Post Status'=>'Uppdatering av slutlig inläggsstatus','Setting the post status based on the "_wpml_import_after_process_post_status" field from the import file (if provided).'=>'Ställer in inläggsstatus baserat på fältet ”_wpml_import_after_process_post_status” från importfilen (om det tillhandahålls).','Identifying Inline Term Languages'=>'Identifiering av språk för inbäddade termer','Identifying and setting the language of terms created during post imports.'=>'Identifierar och ställer in språket för termer som skapats under inläggsimporter.','Setting Posts’ Language'=>'Inställning av inläggens språk','Connecting posts to the default language and translations.'=>'Kopplar inlägg till standardspråket och översättningar.','Setting Terms’ Language'=>'Inställning av termernas språk','Connecting taxonomy terms to the default (original) language and translations.'=>'Kopplar taxonomitermer till standardspråket (originalspråket) och översättningar.','Setting Parent Terms\' Language'=>'Inställning av överordnade termers språk','Assigning language to parent taxonomy terms that don\'t have one, based on the language assigned to their children.'=>'Tilldelar språk till överordnade taxonomitermer som saknar ett, baserat på språket som tilldelats deras underordnade termer.','Migrating your multilingual site? Remember to also install %s on your new site before importing your content so we can restore all the translations.'=>'Ska du migrera din flerspråkiga webbplats? Kom ihåg att även installera %s på din nya webbplats innan du importerar ditt innehåll så att vi kan återställa alla översättningar.','Migrating your multilingual shop? With %1$s and %2$s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'Ska du migrera din flerspråkiga butik? Med %1$s och %2$s kan du överföra ditt översatta innehåll till en ny webbplats, inklusive korsförsäljning, merförsäljning och produktattribut.','Migrating your multilingual shop? Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Ska du migrera din flerspråkiga butik? Kom ihåg att installera %1$s och %2$s på din nya webbplats innan du importerar ditt innehåll så att vi kan återställa alla översättningar.','Looking to import your multilingual content? Remember to install %s in your original site before exporting its content so we can import all the translations here.'=>'Vill du importera ditt flerspråkiga innehåll? Kom ihåg att installera %s på din ursprungliga webbplats innan du exporterar dess innehåll så att vi kan importera alla översättningar hit.','Looking to import your multilingual content? Install %1$s on this site.'=>'Vill du importera ditt flerspråkiga innehåll? Installera %1$s på den här webbplatsen.','Remember to also enable %2$s and %3$s in your original shop before exporting its content so we can import all the translations here.'=>'Kom ihåg att även aktivera %2$s och %3$s i din ursprungliga butik innan du exporterar dess innehåll så att vi kan importera alla översättningar hit.','Looking to import your multilingual content? Remember to enable %1$s and %2$s in your original shop before exporting its content so we can import all the translations here.'=>'Vill du importera ditt flerspråkiga innehåll? Kom ihåg att aktivera %1$s och %2$s i din ursprungliga butik innan du exporterar dess innehåll så att vi kan importera alla översättningar hit.','WooCommerce Multilingual'=>'WooCommerce Multilingual','Switch to all languages'=>'Växla till alla språk','Linking Product Attribute Translations'=>'Länkning av översättningar för produktattribut','Connecting product attributes to their translations based on associated product variations.'=>'Kopplar produktattribut till deras översättningar baserat på tillhörande produktvariationer.','Updating Related Products On Translations'=>'Uppdatering av relaterade produkter i översättningar','Setting up-sells, cross-sells and grouped products references in the right language.'=>'Ställer in referenser för merförsäljning, korsförsäljning och grupperade produkter på rätt språk.','Importing Custom Attribute Labels'=>'Import av anpassade attributetiketter','Importing labels for product-specific (custom) attributes from the exported data.'=>'Importerar etiketter för produktspecifika (anpassade) attribut från den exporterade datan.','You are about to export all your products in all languages at once.'=>'Du håller på att exportera alla dina produkter på alla språk samtidigt.','Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Kom ihåg att installera %1$s och %2$s på din nya webbplats innan du importerar ditt innehåll så att vi kan återställa alla översättningar.','You are about to export your products in %s.'=>'Du håller på att exportera dina produkter på %s.','Registering Product Attributes'=>'Registrering av produktattribut','Identifying and registering attributes created during product imports for translation.'=>'Identifierar och registrerar attribut som skapats under produktimporter för översättning.','Identifying Product Attribute Languages'=>'Identifiering av språk för produktattribut','Identifying and setting the language of attributes created during product imports.'=>'Identifierar och ställer in språket för attribut som skapats under produktimporter.','Export and Import'=>'Export och import','I’m using the built-in %s export/import tool'=>'Jag använder det inbyggda export-/importverktyget i %s','I’m using %s plugin'=>'Jag använder tillägget %s','(%1$d/%2$d items)'=>'(%1$d/%2$d objekt)','%d skipped'=>'%d hoppades över','(no items)'=>'(inga objekt)','Counting items...'=>'Räknar objekt...','First, tell us how you’re going to create the content that you’ll be importing:'=>'Berätta först hur du tänker skapa innehållet som du ska importera:','Continue'=>'Fortsätt','I’m using %1$s and %2$s plugins'=>'Jag använder tilläggen %1$s och %2$s','I’m using a different method to export from this site'=>'Jag använder en annan metod för att exportera från den här webbplatsen','I’m exporting the content from this site'=>'Jag exporterar innehållet från den här webbplatsen','I’m exporting the content from a different website or system'=>'Jag exporterar innehållet från en annan webbplats eller ett annat system','Before importing, add language columns to your content'=>'Lägg till språkkolumner i ditt innehåll före import','Make sure that your import file includes the following columns (custom fields) with language information:'=>'Se till att din importfil innehåller följande kolumner (anpassade fält) med språkinformation:','%s: A value that’s the same for all the translations of each item. In e-commerce sites this will often be the SKU.'=>'%s: Ett värde som är detsamma för alla översättningar av varje objekt. På e-handelswebbplatser är detta ofta artikelnumret (SKU).','%s: The language code for each item.'=>'%s: Språkkoden för varje objekt.','And, you can include these two columns if needed:'=>'Och du kan inkludera dessa två kolumner vid behov:','%s: If this item is a translation, set this column to the code of the source language. If it’s not a translation, keep it empty.'=>'%s: Om det här objektet är en översättning, sätt den här kolumnen till koden för källspråket. Om det inte är en översättning, lämna den tom.','%s: Set to “draft” or “published” to determine the publishing status of the post after adjusting languages. Usually, this value will be “published”.'=>'%s: Sätt till ”draft” eller ”published” för att avgöra inläggets publiceringsstatus efter att språken justerats. Vanligtvis är detta värde ”published”.','Here is an example of importing two items, into your site’s languages (%s):'=>'Här är ett exempel på import av två objekt till din webbplats språk (%s):','Once you’ve added language columns to your multilingual content file, import it to your site using whatever import plugin you prefer.'=>'När du har lagt till språkkolumner i din flerspråkiga innehållsfil kan du importera den till din webbplats med valfritt importtillägg.','Before importing, your content needs language information'=>'Ditt innehåll behöver språkinformation före import','%s will add the necessary language information to your export.'=>'%s kommer att lägga till nödvändig språkinformation i din export.','Import your multilingual content file into the site using whatever import plugin you prefer.'=>'Importera din flerspråkiga innehållsfil till webbplatsen med valfritt importtillägg.','Use your favorite import plugin'=>'Använd ditt favorit-importtillägg','After you import the content, it will still not show the correct language information. So, we recommend that you import new content as Drafts. If you’re importing updates, you can keep already-published content as published.'=>'När du har importerat innehållet kommer det fortfarande inte att visa korrekt språkinformation. Därför rekommenderar vi att du importerar nytt innehåll som utkast. Om du importerar uppdateringar kan du behålla redan publicerat innehåll som publicerat.','Return here, to %s, to set languages and connect translations'=>'Återvänd hit, till %s, för att ställa in språk och koppla översättningar','When you visit this page after you’ve imported content with language information, you’ll be able to run %s to apply languages and connect translations.'=>'När du besöker den här sidan efter att ha importerat innehåll med språkinformation kommer du att kunna köra %s för att tillämpa språk och koppla översättningar.','Already imported and still seeing this screen? %1$sTroubleshooting %2$s%3$s.'=>'Har du redan importerat och ser fortfarande den här skärmen? %1$sFelsökning %2$s%3$s.','How to Export and Import Content in Multiple Languages'=>'Hur man exporterar och importerar innehåll på flera språk','%s is ready to update your imported content'=>'%s är redo att uppdatera ditt importerade innehåll','Good job. We see %1$d terms and %2$d posts that are imported and need language information.'=>'Bra jobbat! Vi hittade %1$d termer och %2$d inlägg som är importerade och behöver språkinformation.','Good job. We see %d terms that are imported and need language information.'=>'Bra jobbat! Vi hittade %d termer som är importerade och behöver språkinformation.','Good job. We see %d posts that are imported and need language information.'=>'Bra jobbat! Vi hittade %d inlägg som är importerade och behöver språkinformation.','Run WPML Import'=>'Kör WPML Import','Multilingual Import Complete'=>'Flerspråkig import slutförd']];